// Options on a stock with discrete cash dividends, from QuantLib, for
// tests/fixtures/dividends.sexp. Europeans by CashDividendEuropeanEngine
// (Healy 2021: spot model, and escrowed), Americans by
// FdBlackScholesVanillaEngine on a fine grid (spot and escrowed models).
// Flat rate, yield and vol, ACT/365F; each dividend is paid on its ex-date.
// One entry per option:
//   (name kind exercise model spot strike rate yield vol valuation expiry
//    ((date amount) ...) npv)
#include <ql/quantlib.hpp>
#include <fstream>
#include <iomanip>

using namespace QuantLib;

struct Case {
    const char* name;
    Real spot, rate, yield, vol;
    Date expiry;
    std::vector<Date> dividendDates;
    std::vector<Real> amounts;
    std::vector<Real> strikes;
};

static std::string iso(const Date& d) {
    std::ostringstream s;
    s << d.year() << "-" << std::setw(2) << std::setfill('0') << int(d.month()) << "-"
      << std::setw(2) << std::setfill('0') << d.dayOfMonth();
    return s.str();
}

int main(int, char** argv) {
    const Date today(26, October, 2026);
    Settings::instance().evaluationDate() = today;
    DayCounter dc = Actual365Fixed();

    const std::vector<Case> cases = {
        {"two-dividends", 100.0, 0.05, 0.0, 0.30, Date(26, October, 2027),
         {Date(25, January, 2027), Date(26, July, 2027)}, {3.0, 3.0}, {90.0, 100.0, 110.0}},
        {"with-yield", 100.0, 0.03, 0.01, 0.25, Date(26, April, 2027),
         {Date(26, January, 2027)}, {2.0}, {95.0, 105.0}},
        {"late-dividend", 100.0, 0.05, 0.0, 0.20, Date(26, October, 2027),
         {Date(27, September, 2027)}, {5.0}, {100.0}},
        // Haug's Roll-Geske-Whaley example in days: t1 = 91/365, T = 122/365.
        {"rgw", 80.0, 0.06, 0.0, 0.30, today + 122, {today + 91}, {4.0}, {82.0}},
    };

    std::ofstream out(argv[1]);
    out << ";;;; Generated by tests/fixtures/generate_dividends.cpp from QuantLib. Do not edit.\n"
        << ";;;; (name kind exercise model spot strike rate yield vol valuation expiry\n"
        << ";;;;  ((ex-date amount) ...) npv)\n(\n"
        << std::setprecision(17);

    for (const auto& c : cases) {
        Handle<Quote> spot(ext::make_shared<SimpleQuote>(c.spot));
        Handle<YieldTermStructure> r(ext::make_shared<FlatForward>(today, c.rate, dc));
        Handle<YieldTermStructure> q(ext::make_shared<FlatForward>(today, c.yield, dc));
        Handle<BlackVolTermStructure> v(
            ext::make_shared<BlackConstantVol>(today, NullCalendar(), c.vol, dc));
        auto process = ext::make_shared<BlackScholesMertonProcess>(spot, q, r, v);
        DividendSchedule dividends = DividendVector(c.dividendDates, c.amounts);

        for (Real k : c.strikes) {
            for (Option::Type type : {Option::Call, Option::Put}) {
                auto payoff = ext::make_shared<PlainVanillaPayoff>(type, k);
                for (bool american : {false, true}) {
                    ext::shared_ptr<Exercise> exercise;
                    if (american)
                        exercise = ext::make_shared<AmericanExercise>(today, c.expiry);
                    else
                        exercise = ext::make_shared<EuropeanExercise>(c.expiry);
                    for (auto model : {CashDividendEuropeanEngine::Spot,
                                       CashDividendEuropeanEngine::Escrowed}) {
                        VanillaOption option(payoff, exercise);
                        if (american)
                            option.setPricingEngine(ext::make_shared<FdBlackScholesVanillaEngine>(
                                process, dividends, 2000, 2000, 100, FdmSchemeDesc::Douglas(),
                                false, -Null<Real>(),
                                model == CashDividendEuropeanEngine::Spot
                                    ? FdBlackScholesVanillaEngine::Spot
                                    : FdBlackScholesVanillaEngine::Escrowed));
                        else
                            option.setPricingEngine(ext::make_shared<CashDividendEuropeanEngine>(
                                process, dividends, model));
                        out << " (\"" << c.name << "\" " << (type == Option::Call ? ":call" : ":put")
                            << (american ? " :american" : " :european")
                            << (model == CashDividendEuropeanEngine::Spot ? " :spot " : " :escrowed ")
                            << c.spot << "d0 " << k << "d0 " << c.rate << "d0 " << c.yield << "d0 "
                            << c.vol << "d0 \"" << iso(today) << "\" \"" << iso(c.expiry) << "\" (";
                        for (std::size_t i = 0; i < c.amounts.size(); ++i)
                            out << "(\"" << iso(c.dividendDates[i]) << "\" " << c.amounts[i]
                                << "d0)";
                        out << ") " << option.NPV() << "d0)\n";
                    }
                }
            }
        }
    }
    out << ")\n";
    return 0;
}
